#include <iostream>
#include <vector>
using namespace std;

bool is_stable(int reading) {
    return reading >= 20 && reading <= 80;
}

int main() {
    int n;
    cin >> n;

    vector<int> readings;
    for (int i = 0; i < n; i++) {
        int val;
        cin >> val;
        readings.push_back(val);
    }

    int stable_count = 0;
    for (int i = 0; i < readings.size(); i++) {
        if (is_stable(readings[i])) {
            stable_count++;
        }
    }

    cout << "STABLE COUNT: " << stable_count << endl;
    return 0;
}

