#include <iostream>
using namespace std;

void trim_channel(int &signal, int baseline, int max_cap) {
    signal -= baseline;
    if (signal > max_cap) {
        signal = max_cap;
    }
    if (signal < 0) {
        signal = 0;
    }
}

int main() {
    int sig, base, cap;
    cin >> sig >> base >> cap;

    trim_channel(sig, base, cap);
    cout << "TRIMMED SIGNAL: " << sig << endl;

    return 0;
}

